class Solution {
  public long countOfSubstrings(String word, int k) {
    return atLeast(word, k) - atLeast(word, k + 1);
  }

  // substrings that contain all five vowels and at least m consonants
  private long atLeast(String word, int m) {
    int n = word.length(), right = 0, consonants = 0, distinctVowels = 0;
    int[] vowels = new int[26];
    long result = 0;
    for (int left = 0; left < n; left++) {
      while (right < n && !(distinctVowels == 5 && consonants >= m)) {
        char c = word.charAt(right++);
        if ("aeiou".indexOf(c) >= 0) {
          if (vowels[c - 'a']++ == 0) distinctVowels++;
        } else {
          consonants++;
        }
      }
      if (distinctVowels == 5 && consonants >= m) result += n - right + 1;
      char c = word.charAt(left);
      if ("aeiou".indexOf(c) >= 0) {
        if (--vowels[c - 'a'] == 0) distinctVowels--;
      } else {
        consonants--;
      }
    }
    return result;
  }
}
